"""Unit tests for the fixed dedupe module."""

import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from dedupe import dedupe


class DedupeOrderTests(unittest.TestCase):
    def test_preserves_first_occurrence_order(self):
        self.assertEqual(dedupe(["b", "a", "b", "c", "a"]), ["b", "a", "c"])

    def test_first_not_last_occurrence_kept(self):
        self.assertEqual(dedupe(["x", "y", "x", "z", "y"]), ["x", "y", "z"])

    def test_no_duplicates_is_unchanged(self):
        self.assertEqual(dedupe(["a", "b", "c"]), ["a", "b", "c"])

    def test_all_elements_identical(self):
        self.assertEqual(dedupe(["a", "a", "a"]), ["a"])

    def test_single_element(self):
        self.assertEqual(dedupe(["only"]), ["only"])

    def test_unicode_strings(self):
        self.assertEqual(dedupe(["café", "naïve", "café"]), ["café", "naïve"])

    def test_empty_strings_allowed(self):
        self.assertEqual(dedupe(["", "a", ""]), ["", "a"])


class DedupeEmptyInputTest(unittest.TestCase):
    def test_empty_list_returns_empty_list(self):
        result = dedupe([])
        self.assertIsInstance(result, list)
        self.assertIsNotNone(result)
        self.assertEqual(result, [])


class DedupeInputValidationTests(unittest.TestCase):
    def test_non_list_input_raises_value_error(self):
        for bad in (("a", "b"), "ab", None, 42, {"a", "b"}):
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    dedupe(bad)

    def test_non_string_elements_raise_value_error(self):
        for bad in (1, None, 3.14, True, ["nested"], (1, 2), {"k": "v"}):
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    dedupe(["ok", bad])

    def test_only_non_string_list_raises_value_error(self):
        with self.assertRaises(ValueError):
            dedupe([1, 2, 3])


class DedupeBehaviorTests(unittest.TestCase):
    def test_does_not_mutate_input(self):
        items = ["a", "b", "a"]
        snapshot = list(items)
        dedupe(items)
        self.assertEqual(items, snapshot)

    def test_returns_new_list(self):
        items = ["a", "b", "a"]
        result = dedupe(items)
        self.assertIsNot(result, items)


if __name__ == "__main__":
    unittest.main()
